from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Iterable, Literal


Eye = Literal["L", "R"]


@dataclass(frozen=True)
class EyeFileRef:
    subject_id: str
    eye: Eye
    absolute_path: str
    relative_path: str
    filename: str


@dataclass(frozen=True)
class SubjectTraversal:
    subject_id: str
    left_files: list[EyeFileRef]
    right_files: list[EyeFileRef]


@dataclass(frozen=True)
class SubjectLookup:
    present: bool
    subject: SubjectTraversal | None = None


def iter_subjects(dataset_root: str) -> Iterable[SubjectTraversal]:
    root = Path(dataset_root)
    for subject_dir in sorted(
        (entry for entry in root.iterdir() if entry.is_dir()),
        key=lambda entry: entry.name,
    ):
        yield _build_subject(root, subject_dir)


def get_subject(dataset_root: str, subject_id: str) -> SubjectLookup:
    root = Path(dataset_root)
    subject_dir = root / subject_id
    if not subject_dir.is_dir():
        return SubjectLookup(present=False, subject=None)
    return SubjectLookup(present=True, subject=_build_subject(root, subject_dir))


def _build_subject(dataset_root: Path, subject_dir: Path) -> SubjectTraversal:
    return SubjectTraversal(
        subject_id=subject_dir.name,
        left_files=_collect_eye_files(dataset_root, subject_dir, "L"),
        right_files=_collect_eye_files(dataset_root, subject_dir, "R"),
    )


def _collect_eye_files(
    dataset_root: Path,
    subject_dir: Path,
    eye: Eye,
) -> list[EyeFileRef]:
    eye_dir = subject_dir / eye
    if not eye_dir.is_dir():
        return []

    files = []
    for file_path in sorted(
        (entry for entry in eye_dir.iterdir() if entry.is_file()),
        key=lambda entry: entry.name,
    ):
        files.append(
            EyeFileRef(
                subject_id=subject_dir.name,
                eye=eye,
                absolute_path=str(file_path.resolve()),
                relative_path=str(file_path.relative_to(dataset_root)),
                filename=file_path.name,
            )
        )
    return files

from __future__ import annotations

from dataclasses import dataclass

from iris_dataset.image_inspector import ImageInspection, SUPPORTED_EXTENSIONS, inspect_image
from iris_dataset.traversal import Eye, EyeFileRef, SubjectTraversal, get_subject, iter_subjects


@dataclass(frozen=True)
class DatasetRow:
    subject_id: str
    eye: str
    image_path: str
    width: int
    height: int
    format: str
    file_size: int


@dataclass(frozen=True)
class AnomalyRow:
    subject_id: str
    issue: str
    eye: str | None = None
    image_path: str | None = None


@dataclass(frozen=True)
class DatasetScanResult:
    dataset_root: str
    subject_count: int
    both_eyes_count: int
    left_only_count: int
    right_only_count: int
    neither_eye_count: int
    left_image_count: int
    right_image_count: int
    dataset_rows: list[DatasetRow]
    anomalies: list[AnomalyRow]


@dataclass(frozen=True)
class SubjectInspection:
    subject_id: str
    present: bool
    left_images: list[str]
    right_images: list[str]


@dataclass(frozen=True)
class SubjectScanClassification:
    both_eyes_count: int
    left_only_count: int
    right_only_count: int
    neither_eye_count: int
    anomaly: AnomalyRow | None = None


@dataclass(frozen=True)
class InspectedFileResult:
    dataset_row: DatasetRow | None
    anomaly: AnomalyRow | None
    image_eye: Eye | None


def scan_dataset(dataset_root: str) -> DatasetScanResult:
    dataset_rows: list[DatasetRow] = []
    anomalies: list[AnomalyRow] = []
    subject_count = 0
    both_eyes_count = 0
    left_only_count = 0
    right_only_count = 0
    neither_eye_count = 0
    left_image_count = 0
    right_image_count = 0

    for subject in iter_subjects(dataset_root):
        subject_count += 1
        subject_classification = _classify_subject(subject)
        both_eyes_count += subject_classification.both_eyes_count
        left_only_count += subject_classification.left_only_count
        right_only_count += subject_classification.right_only_count
        neither_eye_count += subject_classification.neither_eye_count
        if subject_classification.anomaly is not None:
            anomalies.append(subject_classification.anomaly)

        for file_ref in [*subject.left_files, *subject.right_files]:
            inspected_file = _inspect_file_ref(file_ref)
            if inspected_file.dataset_row is not None:
                dataset_rows.append(inspected_file.dataset_row)
            if inspected_file.anomaly is not None:
                anomalies.append(inspected_file.anomaly)
            if inspected_file.image_eye == "L":
                left_image_count += 1
            elif inspected_file.image_eye == "R":
                right_image_count += 1

    return DatasetScanResult(
        dataset_root=dataset_root,
        subject_count=subject_count,
        both_eyes_count=both_eyes_count,
        left_only_count=left_only_count,
        right_only_count=right_only_count,
        neither_eye_count=neither_eye_count,
        left_image_count=left_image_count,
        right_image_count=right_image_count,
        dataset_rows=dataset_rows,
        anomalies=anomalies,
    )


def inspect_subject(dataset_root: str, subject_id: str) -> SubjectInspection:
    lookup = get_subject(dataset_root, subject_id)
    if not lookup.present or lookup.subject is None:
        return SubjectInspection(
            subject_id=subject_id,
            present=False,
            left_images=[],
            right_images=[],
        )

    subject = lookup.subject
    return SubjectInspection(
        subject_id=subject.subject_id,
        present=True,
        left_images=_visible_image_names(subject.left_files),
        right_images=_visible_image_names(subject.right_files),
    )


def _classify_subject(subject: SubjectTraversal) -> SubjectScanClassification:
    left_present = bool(subject.left_files)
    right_present = bool(subject.right_files)

    if left_present and right_present:
        return SubjectScanClassification(1, 0, 0, 0)
    if left_present:
        return SubjectScanClassification(0, 1, 0, 0)
    if right_present:
        return SubjectScanClassification(0, 0, 1, 0)
    return SubjectScanClassification(
        0,
        0,
        0,
        1,
        anomaly=AnomalyRow(subject_id=subject.subject_id, issue="missing_both_eyes"),
    )


def _inspect_file_ref(file_ref: EyeFileRef) -> InspectedFileResult:
    inspection = inspect_image(file_ref)
    if inspection.valid:
        return InspectedFileResult(
            dataset_row=_dataset_row_from_inspection(file_ref, inspection),
            anomaly=None,
            image_eye=file_ref.eye,
        )
    return InspectedFileResult(
        dataset_row=None,
        anomaly=_anomaly_from_file(file_ref, inspection.issue or "corrupted_image"),
        image_eye=None,
    )


def _dataset_row_from_inspection(
    file_ref: EyeFileRef,
    inspection: ImageInspection,
) -> DatasetRow:
    return DatasetRow(
        subject_id=file_ref.subject_id,
        eye=file_ref.eye,
        image_path=file_ref.relative_path,
        width=inspection.width or 0,
        height=inspection.height or 0,
        format=inspection.format or "",
        file_size=inspection.file_size,
    )


def _anomaly_from_file(file_ref: EyeFileRef, issue: str) -> AnomalyRow:
    return AnomalyRow(
        subject_id=file_ref.subject_id,
        eye=file_ref.eye,
        image_path=file_ref.relative_path,
        issue=issue,
    )


def _visible_image_names(files: list[EyeFileRef]) -> list[str]:
    return [
        file_ref.filename
        for file_ref in files
        if file_ref.filename.lower().endswith(tuple(SUPPORTED_EXTENSIONS))
    ]
